import React, { useState } from "react";
import { Link } from "react-router-dom";
import "./Dashboard.css";

function UserDashboard() {
  const user = JSON.parse(localStorage.getItem("user"));
  const [showDropdown, setShowDropdown] = useState(false);

  const toggleDropdown = () => {
    setShowDropdown(!showDropdown);
  };

  return (
    <div className="dashboard">
      <div className="header">
        <div className="logo">RouteMax</div>
        <div className="profile-icon-container" onClick={toggleDropdown}>
          <img
            src="https://cdn-icons-png.flaticon.com/512/1077/1077063.png"
            alt="Profile"
            className="profile-icon"
          />
          {showDropdown && (
            <div className="dropdown">
              <div className="dropdown-info">
                <strong>{user?.name}</strong>
                <p>{user?.email}</p>
              </div>
              <hr />
              <button className="dropdown-btn">Edit Profile</button>
              <button className="dropdown-btn">Logout</button>
            </div>
          )}
        </div>
      </div>
      <div className="content">
        <h2>Welcome, {user?.name}!</h2>
        <p>This is your user dashboard.</p>
        <Link to="/track" className="track-link">📦 Track Parcel</Link>
      </div>
    </div>
  );
}

export default UserDashboard;
